/* From Uiverse.io by vinodjangid07  - Tags: gradient, card, social media, radio, rate, rating, feedback, icons */
.__UIV_SCOPE__ .rating-card {
  width: 280px;
  height: fit-content;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  background: #0f0c29;
  background: linear-gradient(to right bottom, #443e89, #0f0c29);
  padding: 20px 20px;
  border-radius: 10px;
  gap: 10px;
  font-family: Arial, Helvetica, sans-serif;
  box-shadow: 0px 10px 10px rgba(0, 0, 0, 0.058);
}
.__UIV_SCOPE__ .text-wrapper {
  width: 100%;
  height: fit-content;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.__UIV_SCOPE__ .text-primary {
  color: white;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.__UIV_SCOPE__ .text-secondary {
  color: #cccccc;
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0.5px;
}
.__UIV_SCOPE__ .rating-stars-container {
  width: 100%;
  height: 30px;
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .star-label svg {
  fill: rgb(210, 210, 210);
  width: 20px;
  height: auto;
}
.__UIV_SCOPE__ .rating-stars-container input {
  appearance: unset;
}
.__UIV_SCOPE__ .rating-stars-container input:hover ~ .star-label svg {
  fill: rgb(255, 204, 185);
}
.__UIV_SCOPE__ .rating-stars-container input:checked ~ .star-label svg {
  fill: rgb(255, 102, 47);
  animation: slide-in-fwd-center 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}
@keyframes slide-in-fwd-center {
  0% {
    transform: scale(1.6);
  }
  100% {
    transform: scale(1);
  }
}

.__UIV_SCOPE__ .socials-container {
  width: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  padding-top: 20px;
  border-top: 1px solid rgb(150, 150, 150);
}
.__UIV_SCOPE__ .social-button {
  text-decoration: none;
}
.__UIV_SCOPE__ .social-button svg {
  width: 15px;
  fill: rgb(228, 228, 228);
}
.__UIV_SCOPE__ .social-button:hover svg {
  fill: rgb(255, 102, 47);
}
